scripts.script:
// default values for variables
const variables = this.quicktext.variables;
if(variables.length < 1) variables[0] = "lower"; // style to use is 'upper' or 'lower
let style = variables[0];

// Set prefix
let prefix = "Good";
if (style !== 'upper') prefix = prefix.toLowerCase();

// Set time of day
const date = new Date();
if (date.getHours() < 12) return `${prefix} morning`;
if (date.getHours() < 16) return `${prefix} afternoon`;
if (date.getHours() < 21) return `${prefix} evening`;

return `${prefix} evening`;

// scripts/CleanSubject.js

// get subject from email if possible
let { subject } = await this.compose.getComposeDetails();

// detect first prefix
let firstPrefix = "";
if (subject.toLowerCase().startsWith("re: ")) firstPrefix = "Re: ";
if (subject.toLowerCase().startsWith("fwd: ")) firstPrefix = "Fwd: ";

// search and remove all prefixes
let previousLength = 0;
while (previousLength != subject.length) {
  // repeat the process if something gets shortened
  previousLength = subject.length;

  subject = subject.replace(/^(re:\s|r:\s|aw:\s|antw:\s|antwort:\s)/i, ""); // replace "Re: ", "R: ", "Aw: ", "Antw: ", "Antwort: "
  subject = subject.replace(/^(fwd:\s|fw:\s|wg:\s|wt:\s|wtrlt:\s)/i, ""); // replace "Fwd: ", "Fw: ", "Wg: ", "Wt: ", "Wtrlt: "
  subject = subject.replace(/^(Re-\d:\s|Re\[\d\]:\s)/i, ""); // replace "Re-1: ", "Re-2: ", "Re[1]: ", "Re[2]: "
  subject = subject.replace(
    /^(\*\*\*\*SPAM\*\*\*\*\s|\[SPAM\]\s|\[SPAM\?\s\]\s)/i,
    "",
  ); // replace "****Spam**** ", "[Spam] ", "[Spam? ] "
  subject = subject.replace(/^(Automatische Antwort:\s)/i, ""); // replace "Automatische Antwort: "
  subject = subject.replace(
    /^(\[Extern]\s-\s|\[Extern]\s|\[Extern]:\s|Extern:\s)/i,
    "",
  ); // replace "[Extern] - ", "[Extern] ", "[Extern]: ", "Extern: "
  subject = subject.replace(/^(\[Probable Suspicious URLs\]\s)/i, ""); // replace "[Probable Suspicious URLs] "
  subject = subject.trim();
}

// reuse first prefix and change subject
await this.compose.setComposeDetails({ subject: firstPrefix + subject });

// scripts/DateOffset.js

// default values for this.quicktext.variables
if (this.quicktext.variables.length < 1) this.quicktext.variables[0] = "0"; // number of months to add or subtract
if (this.quicktext.variables.length < 2) this.quicktext.variables[1] = "0"; // number of days to add or subtract
if (this.quicktext.variables.length < 3) this.quicktext.variables[2] = "short"; // format to use

// get the current date with an offset (specified by the this.quicktext.variables)
let date = new Date();
let dayOffset = date.getDate() - 1;
let dateOffset = new Date(date.getFullYear(), date.getMonth(), 1);
dateOffset.setMonth(
  dateOffset.getMonth() + parseInt(this.quicktext.variables[0]),
);
dateOffset.setDate(
  dateOffset.getDate() + dayOffset + parseInt(this.quicktext.variables[1]),
);

// options described here: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date/toLocaleDateString
let options = { year: "numeric", month: "long", day: "numeric" };
if (this.quicktext.variables[2].toLowerCase() == "numeric")
  options = { year: "numeric", month: "2-digit", day: "2-digit" };
if (this.quicktext.variables[2].toLowerCase() == "short")
  options = { year: "numeric", month: "long", day: "numeric" };
if (this.quicktext.variables[2].toLowerCase() == "long")
  options = { weekday: "long", year: "numeric", month: "long", day: "2-digit" };
if (this.quicktext.variables[2].toLowerCase() == "yearmonth")
  options = { year: "numeric", month: "long" };
if (this.quicktext.variables[2].toLowerCase() == "year")
  options = { year: "numeric" };
if (this.quicktext.variables[2].toLowerCase() == "monthname")
  options = { month: "long" };
if (this.quicktext.variables[2].toLowerCase() == "weekday")
  options = { weekday: "long" };

// return result; undefined instead of "en-EN" or "de-DE" should use the users language by default
return dateOffset.toLocaleDateString(undefined, options);

// scripts/RemoveRecipients.js

let type = this.quicktext.variables[0];
let details = {};

if (type == "to" || type == "all") {
  details.to = [];
}

if (type == "cc" || type == "all") {
  details.cc = [];
}

if (type == "bcc" || type == "all") {
  details.bcc = [];
}

if (type == "reply-to" || type == "all") {
  details.replyTo = [];
}
await this.compose.setComposeDetails(details);

// scripts/SetSubject.js

let subject = this.quicktext.variables[0];
this.compose.setComposeDetails({ subject });

// scripts/AddRecipients.js
let type = this.quicktext.variables[0];
let adresses = this.quicktext.variables[1].split(";");

if (!type || !["to", "cc", "bcc", "reply-to"].includes(type)) {
  return;
}

if (type == "reply-to") {
  type = "replyTo";
}

let details = await this.compose.getComposeDetails();
let recipients = new Set([...details[type], ...adresses].map((e) => e.trim()));
await this.compose.setComposeDetails({
  [type]: Array.from(recipients),
});

// scripts/GetRecipients.js

let result = "";

let { to, cc, bcc, replyTo } = await this.compose.getComposeDetails();

for (let toAddress of to) {
  result += "To: " + toAddress + "\r\n";
}

for (let ccAddress of cc) {
  result += "CC: " + ccAddress + "\r\n";
}

for (let bccAddress of bcc) {
  result += "BCC: " + bccAddress + "\r\n";
}

for (let replyToAddress of replyTo) {
  result += "Reply to: " + replyToAddress + "\r\n";
}

return result;

// scripts/ConvertTextTo.js

// Variables
const variables = this.quicktext.variables;
const type = variables[0];
let text = variables[1];

// Transformation functions
const transformations = {
  upper: (str) => str.toUpperCase(),
  lower: (str) => str.toLowerCase(),
  title: (str) =>
    str
      .split(" ")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(" "),
};

// Perform the transformation
if (transformations[type]) text = transformations[type](text);

// Return
return text;
